	["And so happened that Leaks A Lot failed to complete the challenge! He landed, pressured by shame ..."] = "Och så hände det att Leaks a Lot misslyckades med utmaningen! Han landade, tyngd av skam ...", -- A_Classic_Fairytale:first_blood
