	["Hint: If this mission panel disappears, you can|see it again by hitting the Pause or Quit key."] = "Tips: Om den här uppdragspanelen försvinner kan du|visa den igen med paus- eller avslutningstangenten.", -- Basic_Training_-_Movement
	["Hint: It might be a good idea to place a girder before starting to drill. Just saying."] = "Tips: Det kan vara bra att placera en balk innan du börjar borra. Bara ett förslag.", -- A_Classic_Fairytale:family
	["Hint: It might be easier if you vary the angle only slightly."] = "Tips: Det kan bli lättare om du bara ändrar vinkeln lite grann.", -- Basic_Training_-_Bazooka
	["Hint: Just select the parachute, it opens automatically when you fall."] = "Tips: Välj bara fallskärmen, så öppnas den automatiskt när du faller.", -- A_Classic_Fairytale:first_blood
	["Hint: Kills won't transfer a hog's pool to the killer's pool"] = "Tips: Att döda en igelkott överför inte dess vapenpool till dödarens", -- Battalion
	["Hint: Launch the bazooka horizontally at full power."] = "Tips: Avfyra raketgeväret vågrätt med full kraft.", -- Basic_Training_-_Bazooka
	["Hint: Pause the game to review the mission texts."] = "Tips: Pausa spelet för att läsa uppdragstexterna igen.", -- A_Classic_Fairytale:first_blood
	["Hint: Select the blow torch, aim and press [Fire]. Press [Fire] again to stop."] = "Tips: Välj blåslampan, sikta och tryck på [Attack]. Tryck på [Attack] igen för att sluta.", -- A_Classic_Fairytale:journey
	["Hint: Select the low gravity and press [Fire]."] = "Tips: Välj låg gravitation och tryck på [Attack].", -- A_Classic_Fairytale:journey
	["Hint: Select the rope, [Up] or [Down] to aim, [Attack] to fire, directional keys to move."] = "Tips: Välj repet, sikta med [Upp] eller [Ned], skjut med [Attack] och rör dig med piltangenterna.", -- A_Classic_Fairytale:first_blood
	["Hint: Select the Shoryuken and hit [Attack].|P.S.: You can use it mid-air."] = "Tips: Välj Shoryuken och tryck på [Attack].|P.S. Du kan använda den i luften.", -- A_Classic_Fairytale:first_blood
	["Hint: %s needs to get really close to the princess!"] = "Tips: %s måste komma riktigt nära prinsessan!", -- A_Classic_Fairytale:family
	["Hint: The rope only bends around objects.|When it doesn't hit anything, it's always straight."] = "Tips: Repet böjs bara runt föremål.|När det inte träffar något är det alltid rakt.", -- Basic_Training_-_Rope
	["Hint: To jump higher, wait a bit before you hit “High Jump” a second time."] = "Tips: Vänta lite innan du trycker på ”Höjdhopp” en andra gång för att hoppa högre.", -- Basic_Training_-_Movement
	["Hint: To place a girder, select it,|then use [Left] and [Right] to select angle and length,|then choose a location for the girder."] = "Tips: Välj balken för att placera den,|använd sedan [Vänster] och [Höger] för att välja vinkel och längd|och välj till sist var balken ska placeras.", -- A_Classic_Fairytale:shadow
	["Hint: Use the quit key to see the team’s continent."] = "Tips: Använd avslutningstangenten för att se lagets kontinent.", -- Continental_supplies
	["Hint: When you shorten the rope, you move faster!|And when you lengthen it, you move slower."] = "Tips: Du rör dig snabbare när du kortar repet!|Och långsammare när du förlänger det.", -- Basic_Training_-_Rope
	["Hint: you might want to stay out of sight and take all the crates...|"] = "Tips: Det kan vara bra att hålla dig dold och ta alla lådor...|", -- A_Classic_Fairytale:journey
	["Hint: You might want to stay out of sight and take all the crates ..."] = "Tips: Det kan vara bra att hålla dig dold och ta alla lådor ...", -- A_Classic_Fairytale:journey
	["His arms are so strong!"] = "Hans armar är så starka!", -- A_Classic_Fairytale:first_blood
	["hits"] = "träffar", -- Basic_Training_-_Bazooka
	["Hit the “Switch Hedgehog” key until you have|selected Cappy, the hedgehog with the cap!"] = "Tryck på ”Byt igelkott” tills du har|valt Cappy, igelkotten med kepsen!", -- Basic_Training_-_Movement
	["Hmm … it's going slower than expected."] = "Hmm … det går långsammare än väntat.", -- A_Classic_Fairytale:queen
	["Hmmm...actually...I didn't either."] = "Hmmm...faktiskt...inte jag heller.", -- A_Classic_Fairytale:enemy
	["Hmmm..."] = "Hmmm...",
	["Hmmm, I’ll have to find some way of moving him off this anti-portal surface."] = "Hmmm, jag måste hitta något sätt att flytta honom från den här portalspärrade ytan.", -- portal
	["Hmmm...it's a draw. How unfortunate!"] = "Hmmm...det blev oavgjort. Så olyckligt!", -- A_Classic_Fairytale:enemy
	["Hmmm...perhaps a little more time will help."] = "Hmmm...lite mer tid kanske hjälper.", -- A_Classic_Fairytale:first_blood
	["Hm ... Now I ran out of fuel."] = "Hm ... Nu tog bränslet slut.", -- A_Space_Adventure:cosmos
	["Hog 100"] = "Hog 100", -- A_Space_Adventure:fruit03
	["Hog 1"] = "Hog 1", -- A_Space_Adventure:fruit03
