	["Hog decar"] = "Hog decar", -- A_Space_Adventure:fruit03
	["Hog dertien"] = "Hog dertien", -- A_Space_Adventure:fruit03
	["Hog %d"] = "Igelkott %d", -- SimpleMission
	["Hog EOF"] = "Hog EOF", -- A_Space_Adventure:fruit03
	["Hogera is definitely the last planet I saved!"] = "Hogera är definitivt den sista planet jag räddar!", -- A_Space_Adventure:final
	["Hogera is safe!"] = "Hogera är räddat!", -- A_Space_Adventure:final
	["Hog exi"] = "Hog exi", -- A_Space_Adventure:fruit03
	["Hog Hephaestus"] = "Hog Hephaestus", -- A_Space_Adventure:fruit03
	["Hog Identity Mode"] = "Ändring av igelkottsidentitet", -- HedgeEditor
	["HOG IDENTITY MODE"] = "ÄNDRING AV IGELKOTTSIDENTITET", -- HedgeEditor
	["Hog III"] = "Hog III", -- A_Space_Adventure:fruit03
	["Hogminator"] = "Hogminator", -- A_Classic_Fairytale:family
	["Hog nueve"] = "Hog nueve", -- A_Space_Adventure:fruit03
	["Hog octo"] = "Hog octo", -- A_Space_Adventure:fruit03
	["Hog onze"] = "Hog onze", -- A_Space_Adventure:fruit03
	["Hog Saturn"] = "Hog Saturn", -- A_Space_Adventure:fruit03
	["Hogs in sight!"] = "Igelkottar i sikte!", -- Continental_supplies
	["Hog Solo and GB"] = "Hog Solo och GB", -- A_Space_Adventure:fruit02
	["Hog Solo"] = "Hog Solo", -- A_Space_Adventure:cosmos, A_Space_Adventure:death01, A_Space_Adventure:death02, A_Space_Adventure:desert01, A_Space_Adventure:desert02, A_Space_Adventure:desert03, A_Space_Adventure:final, A_Space_Adventure:fruit01, A_Space_Adventure:fruit02, A_Space_Adventure:fruit03, A_Space_Adventure:ice01, A_Space_Adventure:ice02, A_Space_Adventure:moon01, A_Space_Adventure:moon02
	["- Hogs will be revived"] = "- Igelkottar återupplivas", -- Capture_the_Flag
	["- Hogs will drop the flag when killed"] = "- Igelkottar tappar flaggan när de dödas", -- Capture_the_Flag
	["Hog two"] = "Hog two", -- A_Space_Adventure:fruit03
	["Hold [Attack] to attach the rope."] = "Håll ned [Attack] för att fästa repet.", -- Basic_Training_-_Rope
	["Hold the Attack key pressed for more power."] = "Håll ned attacktangenten för mer kraft.", -- Basic_Training_-_Bazooka, Basic_Training_-_Grenade
	["Holy shit!"] = "Jävlar!", -- Mutant
	["Homing Bee"] = "Målsökande bi", -- Construction_Mode
	["Honda"] = "Honda", --
	["Honest Lee"] = "Honest Lee", -- A_Classic_Fairytale:enemy
	["Hooks"] = "Hooks", --
	["Hooray! I actually did it! Hogera is safe!"] = "Hurra! Jag klarade det faktiskt! Hogera är räddat!", -- A_Space_Adventure:final
	["Hooray! I've found it, now I have to get back to Captain Lime!"] = "Hurra! Jag hittade den, nu måste jag tillbaka till kapten Lime!", -- A_Space_Adventure:fruit02
	["Hooray! You are a champion!"] = "Hurra! Du är en mästare!", -- A_Space_Adventure:ice02
	["Hopeless case"] = "Hopplöst fall", -- User_Mission_-_RCPlane_Challenge
	["Hop on top of the next flower and advance to the left coast."] = "Hoppa upp på nästa blomma och fortsätt till den vänstra kusten.", -- A_Classic_Fairytale:journey
	["Horns"] = "Horns", --
	["Hostage Situation"] = "Gisslandrama", -- A_Classic_Fairytale:family
	["How can I ever repay you for saving my life?"] = "Hur ska jag någonsin kunna återgälda att du räddade mitt liv?", -- A_Classic_Fairytale:journey
	["How come in a village full of warriors, it's up to me to save it?"] = "Hur kommer det sig att just jag måste rädda en by full av krigare?", -- A_Classic_Fairytale:dragon
	["How could you betray us?"] = "Hur kunde du förråda oss?", -- A_Classic_Fairytale:queen
	["How difficult would you like it to be?"] = "Hur svårt vill du ha det?", -- A_Classic_Fairytale:first_blood
	["HOW DO THEY KNOW WHERE WE ARE?"] = "HUR VET DE VAR VI ÄR?", -- A_Classic_Fairytale:united
	["However, if you fail to do so, she dies a most violent death, just like your friend! Muahahaha!"] = "Men om du misslyckas får hon en mycket våldsam död, precis som din vän! Moahahaha!", -- A_Classic_Fairytale:journey
	["However, if you fail to do so, she dies a most violent death! Muahahaha!"] = "Men om du misslyckas får hon en mycket våldsam död! Moahahaha!", -- A_Classic_Fairytale:journey
	["However, my mates don't agree with me on letting you go..."] = "Mina kamrater håller däremot inte med mig om att släppa dig...", -- A_Classic_Fairytale:dragon
	["However, the army of %s is about to attack any moment now."] = "Men armén under %s kan anfalla när som helst nu.", -- A_Space_Adventure:fruit01
	["How to Rope"] = "Lär dig använda repet", -- Basic_Training_-_Rope
	["How would you like being discriminated against?"] = "Hur skulle du känna dig om du blev diskriminerad?", -- A_Classic_Fairytale:queen
	["Huh?"] = "Va?", -- A_Classic_Fairytale:backstab, A_Classic_Fairytale:queen
	["Hunter"] = "Jägare", --Bazooka, Shotgun, SniperRifle
	["I ain't gonna sit around no more!"] = "Nu tänker jag inte sitta och vänta längre!", -- A_Classic_Fairytale:queen
	["I already said I'm sorry!"] = "Jag har ju redan sagt förlåt!", -- A_Classic_Fairytale:epil
	["I always suspected him!"] = "Jag har alltid misstänkt honom!", -- A_Classic_Fairytale:epil
	["I am going to leave the kids play by themselves."] = "Jag tänker låta barnen leka själva.", -- A_Classic_Fairytale:queen
	["I am not ready for this planet yet. I should visit it when I have found all the other device parts."] = "Jag är inte redo för den här planeten än. Jag borde besöka den när jag har hittat alla andra apparatdelar.", -- A_Space_Adventure:cosmos
	["I am sorry but I was looking for a device that may be hidden somewhere around here."] = "Förlåt, men jag letade efter en apparat som kan vara gömd någonstans här.", -- A_Space_Adventure:fruit02
	["I believe there's more of them."] = "Jag tror att det finns fler av dem.", -- A_Classic_Fairytale:backstab
	["I cannot let you go any further! … burp …"] = "Jag kan inte låta dig gå längre! … rap …", -- A_Classic_Fairytale:queen
	["I can see you have been training diligently."] = "Jag ser att du har tränat flitigt.", -- A_Classic_Fairytale:first_blood
	["I can't believe how blind we were."] = "Jag kan inte fatta hur blinda vi var.", -- A_Classic_Fairytale:epil
	["I can't believe it worked!"] = "Jag kan inte fatta att det fungerade!", -- A_Classic_Fairytale:shadow
	["I can't believe this!"] = "Jag kan inte tro det!", -- A_Classic_Fairytale:enemy
	["I can't believe what I'm hearing!"] = "Jag kan inte tro mina öron!", -- A_Classic_Fairytale:backstab
	["I can't let you go further because …"] = "Jag kan inte låta dig fortsätta eftersom …", -- A_Classic_Fairytale:queen
	["I can't wait any more, I have to save myself!"] = "Jag kan inte vänta längre, jag måste rädda mig själv!", -- A_Classic_Fairytale:shadow
	["Ice Jake"] = "Ice Jake", -- A_Space_Adventure:ice01
	["I could just teleport myself there..."] = "Jag skulle ju kunna teleportera mig dit...", -- A_Classic_Fairytale:family
	["Icy Girder: [3]"] = "Isig balk: [3]", -- HedgeEditor
	["Icy Land: [3]"] = "Isig terräng: [3]", -- HedgeEditor
	["Icy Land"] = "Isig terräng", -- HedgeEditor
	["I'd better get going myself."] = "Jag borde också ge mig av.", -- A_Classic_Fairytale:journey
	["Identity Thief"] = "Identitetstjuv", -- Mutant
	["I didn't until about a month ago."] = "Det visste jag inte förrän för ungefär en månad sedan.", -- A_Classic_Fairytale:enemy
	["I don't care. It's worth a fortune! Good bye, you idiot!"] = "Det struntar jag i. Den är värd en förmögenhet! Hej då, din idiot!", -- A_Space_Adventure:fruit02
	["I don't know how you did that. But good work!|The next one should be easy as cake for you!"] = "Jag vet inte hur du gjorde det där. Men bra jobbat!|Nästa borde vara en barnlek för dig!", -- Basic_Training_-_Rope
	["I don't know if I can forget what you've done!"] = "Jag vet inte om jag kan glömma vad du har gjort!", -- A_Classic_Fairytale:epil
	["I don't know who I can trust anymore."] = "Jag vet inte vem jag kan lita på längre.", -- A_Classic_Fairytale:epil
	["I don't like your tone! You're hurting me!"] = "Jag gillar inte din ton! Du sårar mig!", -- A_Classic_Fairytale:queen
	["I feel something...a place! They will arrive near the circles!"] = "Jag känner något...en plats! De kommer att dyka upp nära cirklarna!", -- A_Classic_Fairytale:backstab
	["If only I had a way..."] = "Om jag bara hade ett sätt...", -- A_Classic_Fairytale:backstab
	["If only I were given a chance to explain my being here..."] = "Om jag bara fick en chans att förklara varför jag är här...", -- A_Classic_Fairytale:first_blood
	["If only one enemy is left, you'll get bonus ammo."] = "När bara en fiende är kvar får du extra ammunition.", -- A_Space_Adventure:death02
	["I forgot that she's the daughter of the chief, too..."] = "Jag glömde att hon också är hövdingens dotter...", -- A_Classic_Fairytale:backstab
	["I found it! Hooray!"] = "Jag hittade den! Hurra!", -- A_Space_Adventure:desert01
	["If some good old explosives were enough to save Hogera …"] = "Om lite gamla hederliga sprängämnen räckte för att rädda Hogera …", -- A_Space_Adventure:final
	["If they try coming here, they can have a taste of my delicious knuckles!"] = "Försöker de komma hit ska de få smaka på mina utsökta knogar!", -- A_Classic_Fairytale:united
	["If you agree to provide the information we need, you will be spared!"] = "Om du ger oss informationen vi behöver blir du skonad!", -- A_Classic_Fairytale:shadow
	["If you can get that crate fast enough, your beloved \"princess\" may go free."] = "Om du hinner ta lådan kan din älskade ”prinsessa” bli fri.", -- A_Classic_Fairytale:journey
	["If you decide to help us, though, we will no longer need to find a new governor for the island."] = "Men om du bestämmer dig för att hjälpa oss behöver vi inte längre hitta en ny guvernör för ön.", -- A_Classic_Fairytale:shadow
	["If you don't want to slip away, you have to keep moving!"] = "Om du inte vill halka i väg måste du fortsätta röra på dig!", -- Basic_Training_-_Movement
	["If you get stuck, use your Desert Eagle or restart the mission!"] = "Om du fastnar kan du använda din Desert Eagle eller starta om uppdraget!", -- A_Classic_Fairytale:journey
	["If you get stuck, use your Desert Eagle or restart the mission!|"] = "Om du fastnar kan du använda din Desert Eagle eller starta om uppdraget!|", -- A_Classic_Fairytale:journey
	["If you help us you can keep the device if you find it but we'll keep everything else."] = "Om du hjälper oss får du behålla apparaten om du hittar den, men vi behåller allt annat.", -- A_Space_Adventure:fruit02
	["If you hurt an enemy, you'll get one third of the damage dealt."] = "Om du skadar en fiende återfår du en tredjedel av skadan du orsakar som hälsa.", -- A_Space_Adventure:death02
	["If you injure a hedgehog you'll get 35% of the damage dealt."] = "Om du skadar en igelkott återfår du 35 % av skadan du orsakar som hälsa.", -- A_Space_Adventure:death02
	["If you just don’t care …"] = "Om du helt enkelt inte bryr dig …", -- Continental_supplies
	["If you kill a hedgehog with the respective weapon your health points will be set to 100."] = "Om du dödar en igelkott med det aktuella vapnet sätts din hälsa till 100.", -- A_Space_Adventure:death02
	["If you kill an enemy, your health will be set to 100."] = "Om du dödar en fiende sätts din hälsa till 100.", -- A_Space_Adventure:death02
	["If you know what I mean..."] = "Om du förstår vad jag menar...", -- A_Classic_Fairytale:shadow
	["If you miss a shot while trying to|re-attach, your rope is gone, too!"] = "Om du missar när du försöker|fästa repet på nytt förlorar du det också!", -- Basic_Training_-_Rope
	["If you say so..."] = "Om du säger det ...", -- A_Classic_Fairytale:shadow
	["If you skip a turn then the turn time left will be added to your next turn."] = "Om du hoppar över en tur läggs den återstående tiden till din nästa tur.", -- A_Space_Adventure:fruit03
	["If you wish to replay, there are other possible endings, too!"] = "Om du vill spela igen finns det andra möjliga slut också!", -- A_Classic_Fairytale:epil
	["Igmund"] = "Igmund", -- User_Mission_-_Nobody_Laugh
	["I grew sick of the oppression! I broke free!"] = "Jag tröttnade på förtrycket! Jag bröt mig fri!", -- A_Classic_Fairytale:queen
	["I guess I can't go far without fuel!"] = "Jag kommer nog inte långt utan bränsle!", -- A_Space_Adventure:cosmos
	["I guess we lost him!"] = "Vi verkar ha skakat av oss honom!", -- A_Space_Adventure:cosmos
	["I guess you'll have to kill them."] = "Du får nog döda dem.", -- A_Classic_Fairytale:dragon
	["I have come to make you an offering..."] = "Jag har kommit för att ge dig ett erbjudande...", -- A_Classic_Fairytale:shadow
	["I have heard that the local tribes say that many years ago some PAotH scientists were dumping their waste here."] = "Jag har hört att de lokala stammarna berättar om PAotH-forskare som dumpade sitt avfall här för många år sedan.", -- A_Space_Adventure:desert01
	["I have more important things to do!"] = "Jag har viktigare saker att göra!", -- A_Classic_Fairytale:queen
	["I have no idea where that mole disappeared...Can you see it?"] = "Jag har ingen aning om vart mullvaden tog vägen...Ser du den?", -- A_Classic_Fairytale:shadow
	["I have only 3 hogs available and they are all cadets."] = "Jag har bara 3 igelkottar tillgängliga och alla är kadetter.", -- A_Space_Adventure:fruit01
	["I have to follow that alien."] = "Jag måste följa efter den där utomjordingen.", -- A_Classic_Fairytale:backstab
	["I have to get back to the village!"] = "Jag måste tillbaka till byn!", -- A_Classic_Fairytale:shadow
	["I have to reach the surface as quickly as I can."] = "Jag måste ta mig till ytan så fort jag kan.", -- A_Space_Adventure:desert02
	["I hope you are prepared for a small challenge, young one."] = "Jag hoppas att du är redo för en liten utmaning, yngling.", -- A_Classic_Fairytale:first_blood
	["I just don't want to sink to your level."] = "Jag vill bara inte sjunka till din nivå.", -- A_Classic_Fairytale:backstab
	["I just forgot all checkpoints of incomplete missions."] = "Jag har precis glömt alla kontrollpunkter i oavslutade uppdrag.", -- A_Space_Adventure:cosmos
	["I just found out that they have captured your princess!"] = "Jag fick just veta att de har tillfångatagit er prinsessa!", -- A_Classic_Fairytale:family
	["I just want the strange device you found!"] = "Jag vill bara ha den konstiga apparaten du hittade!", -- A_Space_Adventure:ice01
	["I just wonder where Ramon and Spiky disappeared..."] = "Jag undrar bara vart Ramon och Spiky tog vägen...", -- A_Classic_Fairytale:journey
	["I know and I'm terribly sorry!"] = "Jag vet, och jag är hemskt ledsen!", -- A_Classic_Fairytale:epil
	["I know, my hero!"] = "Jag vet, min hjälte!", -- A_Classic_Fairytale:epil
	["I know that your resources are low due to the battle but I'll send two of my best hogs to assist you."] = "Jag vet att du har ont om resurser efter striden, men jag skickar två av mina bästa igelkottar för att hjälpa dig.", -- A_Space_Adventure:fruit02
	["I … like being with you, too."] = "Jag … tycker också om att vara med dig.", -- A_Classic_Fairytale:epil
	["I'll get him!"] = "Jag tar honom!", -- A_Space_Adventure:cosmos
	["I'll hold them off while you return to the village!"] = "Jag håller dem tillbaka medan du återvänder till byn!", -- A_Classic_Fairytale:shadow
	["I'll let you know whatever I know about him if you manage to catch me 3 times."] = "Om du lyckas fånga mig 3 gånger berättar jag allt jag vet om honom.", -- A_Space_Adventure:moon02
	["I'll make good use of it."] = "Jag kommer att ha god nytta av den.", -- A_Space_Adventure:cosmos
	["I'll protect you!"] = "Jag skyddar dig!", -- A_Classic_Fairytale:epil
	["I love Dense Cloud now!"] = "Nu älskar jag Dense Cloud!", -- A_Classic_Fairytale:epil
	["I love you."] = "Jag älskar dig.", -- A_Classic_Fairytale:epil
	["I'm afraid I can't let you proceed!"] = "Jag är rädd att jag inte kan låta dig fortsätta!", -- A_Classic_Fairytale:queen
	["I'm afraid we cannot afford that."] = "Jag är rädd att vi inte har råd med det.", -- A_Classic_Fairytale:queen
	["Imagine those targets are the wolves that killed your parents! Take your anger out on them!"] = "Föreställ dig att måltavlorna är vargarna som dödade dina föräldrar! Ta ut din ilska på dem!", -- A_Classic_Fairytale:first_blood
	["I'm...alive? How? Why?"] = "Lever...jag? Hur? Varför?", -- A_Classic_Fairytale:backstab
	["I'm a ninja."] = "Jag är en ninja.", -- A_Classic_Fairytale:dragon
	["I marked the place of their arrival. You're welcome!"] = "Jag har markerat var de kommer att dyka upp. Varsågod!", -- A_Classic_Fairytale:backstab
	["I may lost this battle, but I haven't lost the war yet!"] = "Jag må ha förlorat den här striden, men kriget har jag inte förlorat än!", -- A_Space_Adventure:moon01
	["I'm certain that this is a misunderstanding, fellow hedgehogs!"] = "Jag är säker på att det här är ett missförstånd, kära igelkottar!", -- A_Classic_Fairytale:first_blood
	["I mean, none of you ceased to live."] = "Jag menar, ingen av er slutade leva.", -- A_Classic_Fairytale:enemy
	["I'm getting old for this!"] = "Jag börjar bli för gammal för det här!", -- A_Classic_Fairytale:family
	["I'm getting thirsty..."] = "Jag börjar bli törstig...", -- A_Classic_Fairytale:family
	["I'm glad this is over!"] = "Jag är glad att det är över!", -- A_Classic_Fairytale:epil
	["I'm here to help you rescue her."] = "Jag är här för att hjälpa dig att rädda henne.", -- A_Classic_Fairytale:family
	["I'm living a dream!"] = "Jag lever i en dröm!", -- A_Classic_Fairytale:queen
	["I'm not sure about that!"] = "Det är jag inte så säker på!", -- A_Classic_Fairytale:united
	["IMPORTANT: To see the mission panel again, hold the mission panel key."] = "VIKTIGT: Håll ned tangenten för uppdragspanelen för att visa den igen.", -- Basic_Training_-_Movement
	["IMPORTANT: To see the mission panel again, pause the game."] = "VIKTIGT: Pausa spelet för att visa uppdragspanelen igen.", -- Basic_Training_-_Movement
	["Impressive...you are still dry as the corpse of a hawk after a week in the desert..."] = "Imponerande...du är fortfarande lika torr som en död hök efter en vecka i öknen...", -- A_Classic_Fairytale:first_blood
	["%i ms"] = "%i ms", -- Gravity
	["I'm so glad this is finally over!"] = "Jag är så glad att det äntligen är över!", -- A_Space_Adventure:final
	["I'm so scared!"] = "Jag är så rädd!", -- A_Classic_Fairytale:united
	["I'm still low on hogs. If you are not afraid I could use a set of extra hands."] = "Jag har fortfarande ont om igelkottar. Om du inte är rädd skulle jag behöva lite extra hjälp.", -- A_Space_Adventure:fruit02
	["I'm still with the aliens."] = "Jag står fortfarande på utomjordingarnas sida.", -- A_Classic_Fairytale:queen
	["I'm terribly sorry!"] = "Jag är hemskt ledsen!", -- A_Classic_Fairytale:queen
	["I'm the spy! I've been giving you out!"] = "Jag är spionen! Jag har förrått er!", -- A_Classic_Fairytale:queen
	["In am also entrusting you with some rope."] = "Jag anförtror dig också lite rep.", -- A_Space_Adventure:cosmos
	["In case you haven't noticed, I'm a woman, too!"] = "Om du inte har märkt det så är jag också kvinna!", -- A_Classic_Fairytale:queen
	["Increase the dust storm damage by sacrificing|your invulnerable ammo."] = "Öka dammstormens skada genom att offra|dina osårbarhetsladdningar.", -- Continental_supplies
	["Incredible..."] = "Otroligt...", -- A_Classic_Fairytale:shadow
