	["In each round, the worst hedgehog of the round is eliminated."] = "I varje omgång slås omgångens sämsta igelkott ut.", -- TrophyRace
	["I need to find the others!"] = "Jag måste hitta de andra!", -- A_Classic_Fairytale:backstab
	["I need to get to the other side of this island, fast!"] = "Jag måste snabbt ta mig till andra sidan ön!", -- A_Classic_Fairytale:journey
	["I need to move the tribe!"] = "Jag måste flytta stammen!", -- A_Classic_Fairytale:united
	["I need to prevent their arrival!"] = "Jag måste hindra dem från att komma hit!", -- A_Classic_Fairytale:backstab
	["I need to warn the others."] = "Jag måste varna de andra.", -- A_Classic_Fairytale:backstab
	["In fact, you are the only one that's been acting strangely."] = "Det är faktiskt bara du som har betett dig konstigt.", -- A_Classic_Fairytale:backstab
