	["Interesting idea, haha!"] = "Intressant idé, haha!", -- A_Classic_Fairytale:enemy
	["Interesting! Last time you said you killed a cannibal!"] = "Intressant! Förra gången sa du att du dödade en kannibal!", -- A_Classic_Fairytale:backstab
	["In the Ice Planet Flying Saucer Stadium ..."] = "På isplanetens tefatsarena ...", -- A_Space_Adventure:ice02
	["In the meantime, take these and return to your \"friend\"!"] = "Ta de här så länge och återvänd till din ”vän”!", -- A_Classic_Fairytale:shadow
	["In the stadium, where the best pilots compete ..."] = "På arenan där de bästa piloterna tävlar ...", -- A_Space_Adventure:ice02
	["In this accident, Professor Hogevil lost all his spines on his head!"] = "I olyckan förlorade professor Hogevil alla taggar på huvudet!", -- A_Space_Adventure:moon02
	["In this mission you get %d%% fuel."] = "I det här uppdraget får du %d%% bränsle.", -- User_Mission_-_Diver
	["In this mission you have infinite time."] = "I det här uppdraget har du obegränsat med tid.", -- portal
	["Invalid Placement"] = "Ogiltig placering", -- Construction_Mode
	["Invasion"] = "Invasion", -- A_Classic_Fairytale:united
	["In your best (and only) flight you took out %d crates with one RC plane!"] = "Under din bästa (och enda) flygning slog du ut %d lådor med ett enda radiostyrt flygplan!", -- User_Mission_-_RCPlane_Challenge
	["In your best flight you took out %d crates with one RC plane."] = "Under din bästa flygning slog du ut %d lådor med ett enda radiostyrt flygplan.", -- User_Mission_-_RCPlane_Challenge
	["I regret to end your little odyssey."] = "Det smärtar mig att avsluta din lilla odyssé.", -- A_Classic_Fairytale:queen
	["I saw it with my own eyes!"] = "Jag såg det med egna ögon!", -- A_Classic_Fairytale:shadow
	["I see..."] = "Jag förstår...", -- A_Classic_Fairytale:shadow
	["I see you already took care of your enemies."] = "Jag ser att du redan har tagit hand om dina fiender.", -- A_Classic_Fairytale:dragon
	["I see you have already taken the leap of faith."] = "Jag ser att du redan har vågat ta språnget.", -- A_Classic_Fairytale:first_blood
	["I see you would like his punishment to be more...personal..."] = "Jag förstår att du vill att hans straff ska vara mer...personligt...", -- A_Classic_Fairytale:first_blood
	["I sense another wave of cannibals heading my way!"] = "Jag känner att ännu en våg av kannibaler är på väg mot mig!", -- A_Classic_Fairytale:backstab
	["I sense another wave of cannibals heading our way!"] = "Jag känner att ännu en våg av kannibaler är på väg mot oss!", -- A_Classic_Fairytale:backstab
	["%i s"] = "%i s", -- Gravity
	["I should get myself a portal device, maybe this crate has one."] = "Jag borde skaffa en portabel portalapparat, kanske finns det en i den här lådan.", -- portal
	["I should go now, goodbye!"] = "Jag borde gå nu, hej då!", -- A_Space_Adventure:moon02
	["I shouldn't have drunk that last pint."] = "Jag borde inte ha druckit den där sista ölen.", -- A_Classic_Fairytale:dragon
	["Is this place in my head?"] = "Finns den här platsen bara i mitt huvud?", -- A_Classic_Fairytale:dragon
	["I still can't believe he sold us out like that."] = "Jag kan fortfarande inte fatta att han förrådde oss så där.", -- A_Classic_Fairytale:epil
	["I still can't believe you forgave her!"] = "Jag kan fortfarande inte fatta att du förlät henne!", -- A_Classic_Fairytale:epil
	["I still have to get rid of the crates."] = "Jag måste fortfarande göra mig av med lådorna.", -- A_Classic_Fairytale:dragon
	["Itami"] = "Itami", --
	["It doesn't matter. I won't let that alien hurt my daughter!"] = "Det spelar ingen roll. Jag tänker inte låta den där utomjordingen skada min dotter!", -- A_Classic_Fairytale:dragon
	["I think I love you!"] = "Jag tror att jag älskar dig!", -- A_Classic_Fairytale:epil
	["I think we are safe here."] = "Jag tror att vi är säkra här.", -- A_Classic_Fairytale:backstab
	["I thought their shaman died when he tried our medicine!"] = "Jag trodde att deras schaman dog när han provade vår medicin!", -- A_Classic_Fairytale:shadow
	["It is called 'Hogs of Steel'."] = "Det heter ”Igelkottar av stål”.", -- A_Classic_Fairytale:enemy
	["It is time to practice your fighting skills."] = "Det är dags att träna på att slåss.", -- A_Classic_Fairytale:first_blood
	["It must be a childhood trauma..."] = "Det måste vara ett barndomstrauma...", -- A_Classic_Fairytale:family
	["It must be the aliens!"] = "Det måste vara utomjordingarna!", -- A_Classic_Fairytale:backstab
	["It must be the aliens' deed."] = "Det måste vara utomjordingarnas verk.", -- A_Classic_Fairytale:backstab
	["It must be the cyborgs again!"] = "Det måste vara cyborgerna igen!", -- A_Classic_Fairytale:enemy
	["It needs some practice, but you have infinite lives."] = "Det kräver lite övning, men du har oändligt många liv.", -- Basic_Training_-_Rope
	["I told you, I just found them."] = "Jag sa ju att jag bara hittade dem.", -- A_Classic_Fairytale:backstab
	["It only works in teleportation nodes of your own clan."] = "Det fungerar bara vid din egen klans teleportnoder.", -- Construction_Mode
	["It's a good thing SUDDEN DEATH is 99 turns away..."] = "Tur att det är 99 turer kvar till PLÖTSLIG DÖD...",
	["It's all about the right carrots, you know."] = "Allt handlar om de rätta morötterna, förstår du.", -- A_Classic_Fairytale:epil
	["It's always up to women to clear up the mess men created!"] = "Det är alltid kvinnor som måste reda upp röran som männen ställt till med!", -- A_Classic_Fairytale:dragon
	["It's amazing how quickly our lives can change."] = "Det är otroligt hur snabbt våra liv kan förändras.", -- A_Classic_Fairytale:epil
	["It's an ancient ritual of theirs."] = "Det är en uråldrig ritual de har.", -- A_Classic_Fairytale:queen
	["IT'S A SERIOUS MEDICAL CONDITION!"] = "DET ÄR EN ALLVARLIG SJUKDOM!", -- A_Classic_Fairytale:queen
	["It's a shame, I forgot how to do that!"] = "Synd att jag har glömt hur man gör!", -- A_Classic_Fairytale:family
	["It's a shame, really!"] = "Det är verkligen synd!", -- A_Classic_Fairytale:queen
	["It seems that Professor Hogevil has prepared for your arrival!"] = "Det verkar som om professor Hogevil har förberett sig på din ankomst!", -- A_Space_Adventure:moon01
	["It's empty!"] = "Den är tom!", -- Battalion
	["It's impossible to communicate with the spirits without a shaman."] = "Det går inte att tala med andarna utan en schaman.", -- A_Classic_Fairytale:shadow
	["It's not that easy, so listen carefully:"] = "Det är inte så enkelt, så lyssna noga:", -- Basic_Training_-_Flying_Saucer
	["It's over..."] = "Det är över...", -- A_Classic_Fairytale:shadow
	["It's precious to me!"] = "Den är dyrbar för mig!", -- A_Classic_Fairytale:queen
	["It's time you learned that your actions have consequences!"] = "Det är dags att du lär dig att dina handlingar får konsekvenser!", -- A_Classic_Fairytale:journey
	["It's worth more than wood!"] = "Det är värt mer än trä!", -- A_Classic_Fairytale:enemy
	["It's your fault you're there!"] = "Det är ditt eget fel att du är där!", -- A_Classic_Fairytale:epil
	["It wants our brains!"] = "Den vill åt våra hjärnor!", -- A_Classic_Fairytale:shadow
	["It was all a trick?!"] = "Var allt ett trick?!", -- A_Classic_Fairytale:queen
	["It was all just bad luck!"] = "Allt var bara otur!", -- ClimbHome
	["It was completely useless!"] = "Det var helt meningslöst!", -- A_Space_Adventure:final
	["It was fun to watch."] = "Det var roligt att se på.", -- A_Classic_Fairytale:queen
	["It was fun to watch, though."] = "Men det var roligt att se på.", -- A_Classic_Fairytale:queen
	["It was not a dream, unwise one!"] = "Det var ingen dröm, din dåre!", -- A_Classic_Fairytale:backstab
	["It wasn't her fault!"] = "Det var inte hennes fel!", -- A_Classic_Fairytale:epil
	["It would be wiser to steal the space ship while the PAotH guards are taking a brake!"] = "Det vore klokare att stjäla rymdskeppet medan PAotH-vakterna har rast!", -- A_Space_Adventure:cosmos
	["Ivan"] = "Ivan", --
	["I've made it! Yeah!"] = "Jag klarade det! Ja!", -- A_Space_Adventure:moon01
	["I've seen this before. They just appear out of thin air."] = "Jag har sett det här förut. De dyker bara upp ur tomma intet.", -- A_Classic_Fairytale:united
	["I've thought that the best way to get the device is to let you collect most of the parts for me!"] = "Jag tänkte att det bästa sättet att få apparaten var att låta dig samla de flesta delarna åt mig!", -- A_Space_Adventure:death01
	["I want to play a game..."] = "Jag vill leka en lek...", -- A_Classic_Fairytale:journey
	["I want to see how it handles this!"] = "Jag vill se hur den klarar det här!", -- A_Classic_Fairytale:backstab
	["I was heading home, you see!"] = "Jag var på väg hem, förstår du!", -- A_Classic_Fairytale:queen
	["I was so scared."] = "Jag var så rädd.", -- A_Classic_Fairytale:epil
	["I was told that as the leader of the king's guard, no one knows this world better than you!"] = "Jag har hört att ingen känner den här världen bättre än du, som leder kungens livgarde!", -- A_Space_Adventure:fruit01
	["I will never hand you the parts!"] = "Jag ger dig aldrig delarna!", -- A_Space_Adventure:death01
	["I wish to help you, %s!"] = "Jag vill hjälpa dig, %s!", -- A_Classic_Fairytale:dragon
	["I wonder where Dense Cloud is..."] = "Jag undrar var Dense Cloud är...", -- A_Classic_Fairytale:journey, A_Classic_Fairytale:shadow
	["I wonder why I'm so angry all the time..."] = "Jag undrar varför jag är så arg hela tiden...", -- A_Classic_Fairytale:family
