	["Now for the supreme discipline of saucer flying, the underwater attack."] = "Nu till tefatsflygningens svåraste gren: undervattensanfallet.", -- Basic_Training_-_Flying_Saucer
	["Now go and don't waste more of my time, you coward!"] = "Ge dig av nu och slösa inte mer av min tid, din fegis!", -- A_Space_Adventure:fruit01
	["Now go and play the menu mission to complete the campaign."] = "Spela nu menyuppdraget för att slutföra kampanjen.", -- A_Space_Adventure:death01
