	["No! What have I done?! What have YOU done?!"] = "Nej! Vad har jag gjort?! Vad har DU gjort?!", -- A_Classic_Fairytale:journey
	["No. Where did he come from?"] = "Nej. Var kom han ifrån?", -- A_Classic_Fairytale:shadow
	["Now how do I get on the other side?!"] = "Hur ska jag nu komma till andra sidan?!", -- A_Classic_Fairytale:dragon
	["Now I have to climb these trees"] = "Nu måste jag klättra upp i de här träden", -- A_Space_Adventure:cosmos
