	["No Wind Influence"] = "Ingen vindpåverkan", -- Basic_Training_-_Grenade
	["Now let's try to drop weapons while flying!"] = "Nu ska vi prova att släppa vapen under flygning!", -- Basic_Training_-_Flying_Saucer
	["Now listen carefully! Below us there are tunnels that have been created naturally over the years"] = "Lyssna noga nu! Under oss finns tunnlar som har bildats naturligt under årens lopp", -- A_Space_Adventure:desert01
