	["Of course, but you're … special."] = "Självklart, men du är … speciell.", -- A_Classic_Fairytale:epil
	["Of course I am!"] = "Självklart är jag det!", -- A_Classic_Fairytale:queen
	["Of course I have to save her. What did I expect?!"] = "Så klart är det jag som måste rädda henne. Vad hade jag väntat mig?!", -- A_Classic_Fairytale:family
	["Of course! It's all obvious now!"] = "Självklart! Nu är allt uppenbart!", -- A_Classic_Fairytale:epil
	["Of course, I will observe the battle and intervene if necessary."] = "Självklart. Jag följer striden och ingriper om det behövs.", -- A_Space_Adventure:fruit01
	["OH, COME ON!"] = "ÅH, LÄGG AV!", -- A_Classic_Fairytale:journey
	["Oh man! Learn how to fly!"] = "Men alltså! Lär dig flyga!", -- A_Space_Adventure:ice02
	["Oh, my!"] = "Oj då!", -- A_Classic_Fairytale:first_blood
	["Oh, my! I forgot something!"] = "Oj då! Jag glömde något!", -- A_Classic_Fairytale:queen
	["Oh, my! This is even more entertaining than I've expected!"] = "Oj då! Det här är ännu mer underhållande än jag hade väntat mig!", -- A_Classic_Fairytale:backstab
	["Oh no, not %s!"] = "Åh nej, inte %s!", -- A_Classic_Fairytale:backstab, A_Classic_Fairytale:united
	["Oh no, the companions have betrayed %s and stole the anti-gravity device part!"] = "Åh nej, följeslagarna har förrått %s och stulit delen till antigravitationsapparaten!", -- A_Space_Adventure:fruit02
	["Oh no! You have died. Try again!"] = "Åh nej! Du dog. Försök igen!", -- Basic_Training_-_Flying_Saucer
	["Oh! Please spare me. You can take all my treasures!"] = "Åh! Skona mig, snälla. Du får ta alla mina skatter!", -- A_Space_Adventure:ice01
	["Oh, silly me! I forgot that I'm the shaman."] = "Åh, så dum jag är! Jag glömde att det är jag som är schamanen.", -- A_Classic_Fairytale:backstab
	["Oh, that. We were just having fun!"] = "Åh, det. Vi roade oss bara!", -- A_Classic_Fairytale:queen
	["Oh yeah! You sure know how to rope!"] = "Åh, ja! Du kan verkligen hantera ett rep!", -- Basic_Training_-_Rope
	["Oh yes! I got the device part! Now it belongs to me alone."] = "Åh, ja! Jag fick tag på apparatdelen! Nu är den bara min.", -- A_Space_Adventure:fruit02
	["Okay, I'll be extra careful!"] = "Okej, jag ska vara extra försiktig!", -- A_Space_Adventure:desert01
