	["Weapon specials: Some weapons have special modes (see weapon description)."] = "Vapnens specialfunktioner: Vissa vapen har speciallägen (se vapenbeskrivningen).", -- Continental_supplies
	["Weapons reset: The weapons are reset after each turn."] = "Vapenåterställning: Vapnen återställs efter varje tur.", -- WxW
	["We are indeed."] = "Det är vi verkligen.", -- A_Classic_Fairytale:backstab
	["We can't defeat them!"] = "Vi kan inte besegra dem!", -- A_Classic_Fairytale:shadow
	["We can't hold them up much longer!"] = "Vi kan inte hålla dem tillbaka mycket längre!", -- A_Classic_Fairytale:united
	["We can't let them take over our little island!"] = "Vi kan inte låta dem ta över vår lilla ö!", -- A_Classic_Fairytale:enemy
	["We come in peace! Just let our friends go!"] = "Vi kommer i fred! Släpp bara våra vänner!", -- A_Classic_Fairytale:queen
	["We could just have blown up the meteorite from the the beginning!"] = "Vi kunde ju ha sprängt meteoriten redan från början!", -- A_Space_Adventure:final
	["We don't have time for that now!"] = "Det har vi inte tid med nu!", -- A_Classic_Fairytale:queen
	["We have lost an object which was critical to this mission."] = "Vi har förlorat ett föremål som var avgörande för uppdraget.", -- SimpleMission
	["We have no time to waste..."] = "Vi har ingen tid att förlora ...", -- A_Classic_Fairytale:journey
	["We have nowhere else to live!"] = "Vi har ingen annanstans att bo!", -- A_Classic_Fairytale:enemy
	["We have spotted the enemy! We'll attack when the enemies start gathering!"] = "Vi har siktat fienden! Vi anfaller när de börjar samlas!", -- A_Space_Adventure:fruit02
	["We have to find our folk!"] = "Vi måste hitta vårt folk!", -- A_Classic_Fairytale:queen
	["We have to hurry! Are you armed?"] = "Vi måste skynda oss! Är du beväpnad?", -- A_Space_Adventure:moon01
	["We have to protect the village!"] = "Vi måste skydda byn!", -- A_Classic_Fairytale:united
	["We have to unite and defeat those cylergs!"] = "Vi måste enas och besegra de där cylergerna!", -- A_Classic_Fairytale:enemy
	["Welcome home! Please take a seat"] = "Välkommen hem! Slå dig ned", -- ClimbHome
	["Welcome, Leaks A Lot!"] = "Välkommen, Leaks a Lot!", -- A_Classic_Fairytale:journey
	["Welcome, %s, surprised to see me?"] = "Välkommen, %s! Förvånad över att se mig?", -- A_Space_Adventure:death01
	["Welcome to the Death Planet!"] = "Välkommen till Dödsplaneten!", -- A_Space_Adventure:cosmos
	["Welcome to the Desert Planet!"] = "Välkommen till Ökenplaneten!", -- A_Space_Adventure:cosmos
	["Welcome to the Fruit Planet!"] = "Välkommen till Fruktplaneten!", -- A_Space_Adventure:cosmos
	["Welcome to the meteorite!"] = "Välkommen till meteoriten!", -- A_Space_Adventure:cosmos
	["Welcome to the moon!"] = "Välkommen till månen!", -- A_Space_Adventure:cosmos
	["Welcome to the Planet of Ice!"] = "Välkommen till Isplaneten!", -- A_Space_Adventure:cosmos
	["Well done."] = "Bra gjort.",
	["Well done! Let's destroy the next target!"] = "Bra gjort! Nu förstör vi nästa måltavla!", -- Basic_Training_-_Rope
	["Well done! The next target awaits."] = "Bra gjort! Nästa måltavla väntar.", -- Basic_Training_-_Rope
	["We'll give you a problem then!"] = "Då ska vi ge dig problem!", -- A_Classic_Fairytale:enemy
	["We'll play a game first."] = "Vi leker en lek först.", -- A_Space_Adventure:moon02
	["We'll spare your life for now!"] = "Vi skonar dig för den här gången!", -- A_Classic_Fairytale:backstab
	["Well, that escalated quickly!"] = "Oj, det gick snabbt utför!", -- ClimbHome
	["Well that was an unnecessary act of violence."] = "Det där var onödigt våld.", -- A_Classic_Fairytale:epil
	["Well, that was an unnecessary act of violence."] = "Det där var onödigt våld.", -- A_Classic_Fairytale:epil
	["Well, that was a waste of time."] = "Det där var slöseri med tid.", -- A_Classic_Fairytale:dragon
	["We'll use our communicators to contact you."] = "Vi kontaktar dig med våra kommunikationsapparater.", -- A_Space_Adventure:cosmos
	["Well, well! Isn't that the cutest thing you've ever seen?"] = "Nämen! Är inte det det gulligaste du har sett?", -- A_Classic_Fairytale:journey
	["Well, yes. This was a cyborg television show."] = "Jo, det här var ett tv-program för cyborger.", -- A_Classic_Fairytale:enemy
	["Well, you're about to wake up!"] = "Då är det dags att vakna!", -- A_Classic_Fairytale:queen
	["We made sure noone followed us!"] = "Vi såg till att ingen följde efter oss!", -- A_Classic_Fairytale:backstab
	["We need it to get split into at least two parts."] = "Den måste delas i minst två delar.", -- A_Space_Adventure:cosmos
	["We need to go back!"] = "Vi måste tillbaka!", -- A_Classic_Fairytale:queen
	["We need to hurry!"] = "Vi måste skynda oss!", -- A_Classic_Fairytale:queen
	["We need to move!"] = "Vi måste ge oss av!", -- A_Classic_Fairytale:united
	["We need to prevent their arrival!"] = "Vi måste hindra dem från att komma hit!", -- A_Classic_Fairytale:backstab
	["We need to warn the village."] = "Vi måste varna byn.", -- A_Classic_Fairytale:shadow
	["We need you to go there and detonate them yourself! Good luck!"] = "Du måste ta dig dit och spränga dem själv! Lycka till!", -- A_Space_Adventure:cosmos
	["We oppressed her, the only woman in the tribe!"] = "Vi förtryckte henne, stammens enda kvinna!", -- A_Classic_Fairytale:epil
	["We're terribly sorry!"] = "Vi är hemskt ledsna!", -- A_Classic_Fairytale:epil
	["We risk our lives going through challenges."] = "Vi riskerar livet i alla dessa prövningar.", -- A_Classic_Fairytale:queen
	["We should better report this and continue our watch!"] = "Det är bäst att vi rapporterar det här och fortsätter hålla vakt!", -- A_Space_Adventure:cosmos
	["We should head back to the village now."] = "Vi borde gå tillbaka till byn nu.", -- A_Classic_Fairytale:shadow
	["We, the youth, have to constantly prove our value."] = "Vi unga måste hela tiden bevisa vårt värde.", -- A_Classic_Fairytale:queen
	["We trusted you, you fool!"] = "Vi litade på dig, din dåre!", -- A_Classic_Fairytale:queen
	["We were trying to save her and we got lost."] = "Vi försökte rädda henne och gick vilse.", -- A_Classic_Fairytale:family
	["We were your home! Your family!"] = "Vi var ditt hem! Din familj!", -- A_Classic_Fairytale:queen
	["We won't accept you destroying our village!"] = "Vi accepterar inte att du förstör vår by!", -- A_Classic_Fairytale:queen
	["We won't let you hurt any more of us!"] = "Vi låter dig inte skada fler av oss!", -- A_Classic_Fairytale:queen
	["We won't let you hurt her!"] = "Vi låter dig inte skada henne!", -- A_Classic_Fairytale:journey
	["We work and work until we sweat blood."] = "Vi sliter och sliter tills vi svettas blod.", -- A_Classic_Fairytale:queen
	["What?! A cannibal? Here? There is no time to waste! Come, you are prepared."] = "Vad?! En kannibal? Här? Ingen tid att förlora! Kom, du är redo.", -- A_Classic_Fairytale:first_blood
	["What?!"] = "Vad?!", -- A_Classic_Fairytale:queen
	["What a douche!"] = "Vilket svin!", -- A_Classic_Fairytale:enemy
	["What am I gonna...eat, yo?"] = "Men vad ska jag ... äta då?", -- A_Classic_Fairytale:family
	["What are you doing at a distance so great, young one?"] = "Vad gör du så långt borta, yngling?", -- A_Classic_Fairytale:first_blood
	["What are you doing? Let her go!"] = "Vad gör du? Släpp henne!", -- A_Classic_Fairytale:journey
	["What a ride!"] = "Vilken åktur!", -- A_Classic_Fairytale:shadow
	["What a strange cave!"] = "Vilken märklig grotta!", -- A_Classic_Fairytale:dragon
	["What a strange feeling!"] = "Vilken konstig känsla!", -- A_Classic_Fairytale:backstab
	["What could you possibly forget in that cage?"] = "Vad kan du ha glömt i den där buren?", -- A_Classic_Fairytale:queen
	["What does it look like?"] = "Vad ser det ut som?", -- A_Classic_Fairytale:queen
	["What do my faulty eyes observe? A spy!"] = "Vad skådar mina svaga ögon? En spion!", -- A_Classic_Fairytale:first_blood
	["What do you say? Are you in?"] = "Vad säger du? Är du med?", -- A_Space_Adventure:fruit02
	["What do you say? Will you fight for us?"] = "Vad säger du? Vill du slåss för oss?", -- A_Space_Adventure:fruit01
	["What do you want to do?"] = "Vad vill du göra?", -- A_Space_Adventure:fruit01
	["Whatever floats your boat..."] = "Gör som du vill ...", -- A_Classic_Fairytale:shadow
	["What?! For all this struggle I just win some ... time? Oh dear!"] = "Va?! Efter allt det här vinner jag bara lite ... tid? Jösses!", -- portal
	["What has %s ever done to you?"] = "Vad har %s någonsin gjort dig?", -- A_Classic_Fairytale:backstab
	["What? Here? How did they find us?!"] = "Vad? Här? Hur hittade de oss?!", -- A_Classic_Fairytale:backstab
	["What? Is it over already?"] = "Va? Är det redan slut?", -- ClimbHome
	["What is it that you forgot?"] = "Vad är det du har glömt?", -- A_Classic_Fairytale:queen
	["What is this place?"] = "Vad är det här för plats?", -- A_Classic_Fairytale:dragon, A_Classic_Fairytale:enemy
	["What oppression? You were the most unoppressed member of the tribe!"] = "Vilket förtryck? Du var den minst förtryckta i hela stammen!", -- A_Classic_Fairytale:queen
	["What shall we do with the traitor?"] = "Vad ska vi göra med förrädaren?", -- A_Classic_Fairytale:backstab
	["What's in the box, you ask? Let's find out!"] = "Undrar du vad som finns i lådan? Vi tar reda på det!", -- Basic_Training_-_Movement
	["What the?"] = "Vad i ...?", -- A_Classic_Fairytale:queen
	["WHAT?! You're the ones attacking us!"] = "VA?! Det är ju ni som attackerar oss!", -- A_Classic_Fairytale:enemy
	["When?"] = "När?", -- A_Classic_Fairytale:enemy
	["When I find it..."] = "När jag hittar den ...", -- A_Classic_Fairytale:dragon
	["When you're in mid-air, you can continue to aim|and fire another rope if you're not attached."] = "När du är i luften kan du fortsätta sikta|och skjuta repet igen om du har släppt taget.", -- Basic_Training_-_Rope
	["Where are all these crates coming from?!"] = "Var kommer alla lådor ifrån?!", -- A_Classic_Fairytale:shadow
	["Where are they?!"] = "Var är de?!", -- A_Classic_Fairytale:backstab
	["Where did that alien run?"] = "Vart sprang utomjordingen?", -- A_Classic_Fairytale:dragon
	["Where did you get the exploding apples?"] = "Var fick du de exploderande äpplena ifrån?", -- A_Classic_Fairytale:shadow
	["Where did you get the exploding apples and the magic bow that shoots many arrows?"] = "Var fick du de exploderande äpplena och den magiska bågen som skjuter många pilar ifrån?", -- A_Classic_Fairytale:shadow
	["Where did you get the magic bow that shoots many arrows?"] = "Var fick du den magiska bågen som skjuter många pilar ifrån?", -- A_Classic_Fairytale:shadow
	["Where did you get the weapons in the forest, Dense Cloud?"] = "Var fick du vapnen i skogen ifrån, Dense Cloud?", -- A_Classic_Fairytale:backstab
	["Where do you get that?!"] = "Vad har du fått det ifrån?!", -- A_Classic_Fairytale:enemy
	["Where have you been?!"] = "Var har du varit?!", -- A_Classic_Fairytale:backstab
	["Where have you been?"] = "Var har du varit?", -- A_Classic_Fairytale:united
	["While in modification mode, you can change|the LandFlag by clicking on an object."] = "I ändringsläget kan du ändra terrängflaggan|genom att klicka på ett föremål.", -- HedgeEditor
	["White Tee"] = "White Tee", -- A_Space_Adventure:ice01
	["Who's there?! I'll get you!"] = "Vem där?! Jag ska ta dig!", -- A_Space_Adventure:desert01
	["Why?"] = "Varför?", -- A_Classic_Fairytale:queen
	["Why are you doing this?"] = "Varför gör du det här?", -- A_Classic_Fairytale:journey
	["Why are you helping us, uhm...?"] = "Varför hjälper du oss, öh ...?", -- A_Classic_Fairytale:family
	["Why can't he just let her go?!"] = "Varför kan han inte bara släppa henne?!", -- A_Classic_Fairytale:family
	["… why did I risk my life to collect all the parts of the anti-gravity device?"] = "… varför riskerade jag livet för att samla alla delar till antigravitationsapparaten?", -- A_Space_Adventure:final
	["Why did you do this?"] = "Varför gjorde du det här?", -- A_Classic_Fairytale:queen
	["Why did you kill your father?"] = "Varför dödade du din pappa?", -- A_Classic_Fairytale:queen
	["Why do men keep hurting me?"] = "Varför fortsätter män att såra mig?", -- A_Classic_Fairytale:first_blood
	["Why do you always have to call me names?"] = "Varför måste du alltid kalla mig saker?", -- A_Classic_Fairytale:queen
	["Why do you keep betraying us?"] = "Varför fortsätter du att förråda oss?", -- A_Classic_Fairytale:queen
	["Why do you not like me?"] = "Varför tycker du inte om mig?", -- A_Classic_Fairytale:shadow
	["Why do you want to take over our island?"] = "Varför vill ni ta över vår ö?", -- A_Classic_Fairytale:enemy
	["Why me?!"] = "Varför jag?!", -- A_Classic_Fairytale:backstab
	["Why %s? Why?"] = "Varför, %s? Varför?", -- A_Classic_Fairytale:backstab
	["Why, why, why, why!"] = "Varför, varför, varför, varför!", -- A_Classic_Fairytale:queen
	["Why would they do this?"] = "Varför skulle de göra det?", -- A_Classic_Fairytale:backstab
	["- Will get 1-3 random weapons"] = "- Får 1–3 slumpmässiga vapen", -- Continental_supplies
	["- Will Get 1-3 random weapons"] = "- Får 1–3 slumpmässiga vapen", -- Continental_supplies
	["- Will give you a parachute every second turn."] = "- Ger dig en fallskärm varannan tur.", -- Continental_supplies
	["Will this ever end?"] = "Tar det här aldrig slut?",
	["Will you give me the other parts?"] = "Ger du mig de andra delarna?", -- A_Space_Adventure:death01
	["Win"] = "Vinn", -- A_Space_Adventure:ice01
	["Wind"] = "Vind", -- Basic_Training_-_Bazooka
	["Winner: %s"] = "Vinnare: %s", -- Mutant
	["Winning time: %s"] = "Vinnartid: %s", -- Racer, TechRacer
	["Wise Oak"] = "Wise Oak", -- A_Classic_Fairytale:backstab, A_Classic_Fairytale:dragon, A_Classic_Fairytale:enemy, A_Classic_Fairytale:epil, A_Classic_Fairytale:family, A_Classic_Fairytale:queen
	["With Dense Cloud on the land of shadows, I'm the village's only hope..."] = "Nu när Dense Cloud är i skuggornas land är jag byns enda hopp ...", -- A_Classic_Fairytale:journey
	["With low bounciness, it barely bounces at all, but it is much more predictable."] = "Med låg studsstyrka studsar den knappt alls, men blir mycket mer förutsägbar.", -- Basic_Training_-_Grenade
	["With the rest of the tribe gone, it was up to %s to save the village."] = "När resten av stammen var borta var det upp till %s att rädda byn.", -- A_Classic_Fairytale:dragon
	["Worry not, for it is a peaceful animal! There is no reason to be afraid..."] = "Oroa dig inte, det är ett fredligt djur! Du behöver inte vara rädd ...", -- A_Classic_Fairytale:first_blood
	["Wow, what a dream!"] = "Oj, vilken dröm!", -- A_Classic_Fairytale:backstab
	["Xeli"] = "Xeli", --
	["Xerxes"] = "Xerxes", --
	["Y3K1337"] = "Y3K1337", -- A_Classic_Fairytale:journey, A_Classic_Fairytale:shadow
	["Yay, we won!"] = "Hurra, vi vann!", -- A_Classic_Fairytale:enemy
	["Y Chwiliad"] = "Y Chwiliad", -- A_Classic_Fairytale:dragon
	["Yeah...I think it's a 'he', lol."] = "Jo ... jag tror att det är en ”han”, haha.", -- A_Classic_Fairytale:shadow
	["Yeah, sure! I died. Hilarious!"] = "Ja, visst! Jag dog. Jätteroligt!", -- A_Classic_Fairytale:backstab
	["Yeah, sure! I died. Hillarious!"] = "Ja, visst! Jag dog. Jätteroligt!", -- A_Classic_Fairytale:backstab
	["Yeah, take that!"] = "Ja, där fick du!", -- A_Classic_Fairytale:dragon
	["Yeah? Watcha gonna do? Cry?"] = "Jaså? Vad tänker du göra? Gråta?", -- A_Classic_Fairytale:journey
	["Yeah, well, for some dude to be happy, some other dude has to suffer."] = "Tja, för att någon ska få vara lycklig måste någon annan lida.", -- A_Classic_Fairytale:queen
	["Yellow"] = "Gul", --
	["Yellow Pepper"] = "Yellow Pepper", -- A_Space_Adventure:fruit01
	["Yellow Watermelons"] = "Gula vattenmelonerna", -- A_Space_Adventure:fruit01
	["Yes!"] = "Ja!", -- A_Classic_Fairytale:enemy
	["Yes, but you're … different!"] = "Ja, men du är … annorlunda!", -- A_Classic_Fairytale:queen
	["Yes, yeees! You are now ready to enter the real world!"] = "Ja, jaaa! Nu är du redo för den verkliga världen!", -- A_Classic_Fairytale:first_blood
	["Yeti"] = "Yeti", --
	["Yikes!"] = "Hjälp!", -- A_Space_Adventure:desert01
	["Yo, dude! Get away from our weapons!"] = "Hörru, bort från våra vapen!", -- A_Classic_Fairytale:queen
	["Yo, dude, we're here, too!"] = "Hallå, vi är också här!", -- A_Classic_Fairytale:family
	["Yo, escort my buttocks!"] = "Du, eskortera mitt arsle!", -- A_Classic_Fairytale:queen
	["Yoshi"] = "Yoshi", --
	["Yo, the aliens gave me plants. Medicinal plants. Lots of it."] = "Jo, utomjordingarna gav mig växter. Medicinalväxter. Massor.", -- A_Classic_Fairytale:queen
	["You are far from home, and the water is rising, climb up as high as you can!|Your score will be based on your height."] = "Du är långt hemifrån och vattnet stiger. Klättra så högt du kan!|Dina poäng avgörs av höjden du når.", -- ClimbHome
	["You are given the chance to turn your life around..."] = "Du får chansen att förändra ditt liv ...", -- A_Classic_Fairytale:shadow
	["You are in control of all the active ally units."] = "Du styr alla aktiva allierade enheter.", -- A_Space_Adventure:fruit01
	["You are indeed the best PAotH pilot."] = "Du är verkligen PAotH:s bästa pilot.", -- A_Space_Adventure:desert03
	["You are out of danger, time to go to the moon!"] = "Du är utom fara. Dags att åka till månen!", -- A_Space_Adventure:cosmos
	["You are playing with our lives here!"] = "Du leker med våra liv!", -- A_Classic_Fairytale:enemy
	["You are sabotaged, RUN!"] = "Du har utsatts för sabotage, SPRING!", -- Continental_supplies
	["You are the one who fled! So, you are alive."] = "Du är den som flydde! Så du lever.", -- A_Space_Adventure:fruit02
	["You bear impressive skills, %s!"] = "Du är imponerande skicklig, %s!", -- A_Classic_Fairytale:dragon
	["You can also hold down the key for “Precise Aim” to prevent slipping."] = "Du kan också hålla ned tangenten för ”Precisionssikte” för att inte halka.", -- Basic_Training_-_Movement
	["You can always trust me!"] = "Du kan alltid lita på mig!", -- A_Classic_Fairytale:epil
	["You can always trust me! I love you!"] = "Du kan alltid lita på mig! Jag älskar dig!", -- A_Classic_Fairytale:epil
	["You can avoid some battles."] = "Du kan undvika vissa strider.", -- A_Space_Adventure:desert01
	["You can change the detonation timer of grenades."] = "Du kan ställa in granaternas tändtid.", -- Basic_Training_-_Grenade
	["You can choose another planet by replaying this mission."] = "Du kan välja en annan planet genom att spela om det här uppdraget.", -- A_Space_Adventure:cosmos
	["You can dive with your flying saucer!"] = "Du kan dyka med ditt flygande tefat!", -- Basic_Training_-_Flying_Saucer
	["You can even change your aiming direction in mid-flight if you first hold [Precice] and then press [Up] or [Down]."] = "Du kan till och med ändra siktet i luften genom att hålla ned [Precision] och sedan trycka på [Upp] eller [Ned].", -- Basic_Training_-_Flying_Saucer
	["You can even change your aiming direction in mid-flight if you first hold [Precise] and then press [Up] or [Down]."] = "Du kan till och med ändra siktet i luften genom att hålla ned [Precision] och sedan trycka på [Upp] eller [Ned].", -- Basic_Training_-_Flying_Saucer
	["You can further customize the race by changing the scheme script paramater."] = "Du kan anpassa loppet ytterligare genom att ändra spelschemats skriptparameter.", -- TechRacer
	["You can further customize the race by changing the scheme script parameter."] = "Du kan anpassa loppet ytterligare genom att ändra spelschemats skriptparameter.", -- TechRacer
	["You can only use the sniper rifle or the watermelon bomb."] = "Du får bara använda prickskyttegeväret och vattenmelonbomben.", -- A_Space_Adventure:fruit03
	["You can practice moving around and using utilities in this mission.|However, it will never end!"] = "I det här uppdraget kan du öva på att förflytta dig och använda verktyg.|Men det tar aldrig slut!", -- A_Classic_Fairytale:epil
	["You can set the bounciness of grenades (and grenade-like weapons)."] = "Du kan ställa in studsstyrkan för granater och granatliknande vapen.", -- Basic_Training_-_Grenade
	["- You can switch between hogs at the start of your turns. (Not first one)"] = "- Du kan byta igelkott i början av dina turer (utom den första).", -- Continental_supplies
	["You can’t open a portal on the blue surface."] = "Du kan inte öppna en portal på den blå ytan.", -- portal
	["You can use the other 2 hogs to assist you."] = "Du kan använda de 2 andra igelkottarna som hjälp.", -- A_Space_Adventure:fruit02
	["You can use the rope to reach new places."] = "Du kan använda repet för att nå nya platser.", -- Basic_Training_-_Rope
	["You choose well, %s!"] = "Du valde klokt, %s!", -- A_Space_Adventure:fruit01
	["You completed the mission in %.3f seconds."] = "Du klarade uppdraget på %.3f sekunder.", -- A_Space_Adventure:ice02
	["You completed the mission in %d rounds."] = "Du klarade uppdraget på %d omgångar.", -- A_Space_Adventure:death02, A_Space_Adventure:fruit03
	["You couldn't have come to a worse time, %s!"] = "Du kunde inte ha kommit vid ett sämre tillfälle, %s!", -- A_Space_Adventure:fruit01
	["You couldn't possibly believe that after refusing my offer I'd just let you go!"] = "Du trodde väl inte att jag bara skulle släppa dig efter att du avvisat mitt erbjudande!", -- A_Classic_Fairytale:journey
	["You'd almost swear the water was rising!"] = "Man skulle nästan kunna svära på att vattnet stiger!",
	["You'd better watch your steps..."] = "Du bör se dig för ...", -- A_Classic_Fairytale:journey
	["You defended yourself against Captain Lime."] = "Du försvarade dig mot kapten Lime.", -- A_Space_Adventure:fruit02
	["You defended yourself against %s."] = "Du försvarade dig mot %s.", -- A_Space_Adventure:fruit02
	["You did great, %s! However, we aren't out of danger yet!"] = "Bra gjort, %s! Men vi är inte utom fara än!", -- A_Space_Adventure:cosmos
